select product_id, case when unit_price >= 450 then 'high' when unit_price >= 80 then 'mid' else 'low' end unit_price_bucket, count(quantity) quantity_count, max(unit_price) - min(unit_price) unit_price_range, sum(quantity * unit_price) revenue from order_items group by product_id, case when unit_price >= 450 then 'high' when unit_price >= 80 then 'mid' else 'low' end order by unit_price_range, 5 desc
